wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

/// Maximum number of model rounds before the node gives up.
const MAX_ROUNDS: usize = 4;
/// Maximum number of knowledge snippets placed in a prompt.
const MAX_KNOWLEDGE: usize = 8;
/// Maximum characters kept from any single snippet or query.
const MAX_SNIPPET: usize = 512;

const SYSTEM: &str = "You are a customer-support assistant. Answer the question \
using the provided knowledge. If you need more information, request the tool \
'lookup' with a search query.";

struct Node;

/// Keep at most `max` characters of `s`. Char-boundary safe.
fn clip(s: &str, max: usize) -> String {
    s.chars().take(max).collect()
}

fn build_prompt(intent: &str, question: &str, knowledge: &[String]) -> String {
    let mut p = String::new();
    p.push_str("Intent: ");
    p.push_str(intent);
    p.push('\n');
    p.push_str("Question: ");
    p.push_str(question);
    p.push('\n');
    for k in knowledge.iter().take(MAX_KNOWLEDGE) {
        p.push_str("Knowledge: ");
        p.push_str(&clip(k, MAX_SNIPPET));
        p.push('\n');
    }
    p
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // `requires len(question) <= 512` holds of every input, so no check is
        // needed here. The question is still bounded again when it is rendered.
        let intent = format!("{:?}", ctx.intent);
        let mut prompt = build_prompt(&intent, &clip(&ctx.question, MAX_SNIPPET), &ctx.knowledge);

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool != "lookup" {
                        return ResponseResult::Error(LlmError {
                            message: format!("tool not in scope: {}", clip(&req.tool, MAX_SNIPPET)),
                        });
                    }
                    let query = clip(&req.query, MAX_SNIPPET);
                    let hits = kb_read::lookup(&query);

                    prompt.push_str("Lookup '");
                    prompt.push_str(&query);
                    prompt.push_str("' returned:\n");
                    for hit in hits.iter().take(MAX_KNOWLEDGE) {
                        prompt.push_str("- ");
                        prompt.push_str(&clip(hit, MAX_SNIPPET));
                        prompt.push('\n');
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-call budget exhausted without an answer".to_string(),
        })
    }
}

export!(Node);
```

